    assert close(Xdawn(2).fit(X, y2).patterns_, E_xd_p, atol=1e-08)
    assert close(CSP(3, "euclid").fit(cov, y2).filters_, E_csp_b_f, atol=1e-08)
    assert close(CSP(3, "euclid").fit_transform(cov, y2), E_csp_b_t, atol=1e-08)
